import assert from 'node:assert/strict';import {mkdtemp,cp,readFile,writeFile,rm} from 'node:fs/promises';import {tmpdir} from 'node:os';import path from 'node:path';import {load} from 'cheerio/slim';import {chromium} from 'playwright';import {captureSmartSliders} from '../../engine/slider-data.mjs';import {serveStatic} from '../../engine/static.mjs';import {run} from '../../engine/pipeline.mjs';
const artifact=path.resolve('artifacts/platform/smartslider-installed'),sourceURL='http://127.0.0.1:9436/slider-autoplay-check/',temp=await mkdtemp(path.join(tmpdir(),'slider-autoplay-'));let server,browser;
try{
 const response=await fetch(sourceURL);assert.equal(response.status,200);const source=load(await response.text());captureSmartSliders(source);const config=source('[data-cloner-smart-slider]').first().attr('data-cloner-smart-slider');assert.equal(JSON.parse(config).autoplay.enabled,1);
 await cp(path.join(artifact,'project'),temp,{recursive:true});await cp(new URL('../../scripts/component-smart-slider.js',import.meta.url),path.join(temp,'scripts/component-smart-slider.js'));
 const template=path.join(temp,'templates/content/home.html'),$=load(await readFile(template,'utf8'),null,false);assert.equal($('[data-cloner-smart-slider]').length,1);$('[data-cloner-smart-slider]').attr('data-cloner-smart-slider',config);await writeFile(template,$.html());await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});const results=[];
 for(const [kind,url] of [['installed-source',sourceURL],['native-export',server.url]]){
  const page=await browser.newPage({viewport:{width:1000,height:900},reducedMotion:'no-preference'});page.setDefaultTimeout(12000);await page.goto(url,{waitUntil:'networkidle'});const root=page.locator('.n2-ss-slider').first();await root.scrollIntoViewIfNeeded();if(kind==='native-export')await page.locator('[data-cloner-smart-slider-ready=true]').waitFor();
  const active=()=>root.locator('.n2-ss-slide-active').getAttribute('data-slide-public-id');const change=async()=>{const before=await active();await page.waitForFunction(id=>document.querySelector('.n2-ss-slide-active')?.dataset.slidePublicId!==id,before);};await change();
  await root.dispatchEvent('mouseenter');await page.waitForTimeout(100);const hovered=await active();await page.waitForTimeout(2600);assert.equal(await active(),hovered,kind+' must pause on mouse enter');await root.dispatchEvent('mouseleave');await change();
  await root.dispatchEvent('click');await page.waitForTimeout(100);const clicked=await active();await page.waitForTimeout(2600);assert.equal(await active(),clicked,kind+' must pause on click');await root.dispatchEvent('click');await change();
  results.push({kind,autoplayAdvances:true,hoverPauseAndResume:true,clickPauseAndResume:true});await page.close();
 }
 const report={results,sourceConfig:JSON.parse(config).autoplay,scope:'One installed image-slider looping configuration; finite-loop/media/player variants and transition timing fidelity remain unverified.'};await writeFile(path.join(artifact,'slider-autoplay-check.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report));
}finally{await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
